package com.example.conexionrealtimedatabase;
import android.app.*;import android.os.Bundle;import android.view.View;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;
public class AppointmentActivity extends Activity{
 private String initialDate, initialTime; private PatientStore store;private String id,date,time;private EditText reason;private LinearLayout list;private Button dateButton,timeButton;
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new PatientStore(this);id=getIntent().getStringExtra("nuhsa");getWindow().setStatusBarColor(Ui.BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);Calendar c=Calendar.getInstance();int m=((c.get(Calendar.MINUTE)+4)/5)*5;if(m>=60){c.add(Calendar.HOUR_OF_DAY,1);m=0;}date=fmtDate(c);time=String.format(Locale.getDefault(),"%02d:%02d",c.get(Calendar.HOUR_OF_DAY),m);LinearLayout page=Ui.page(this);Patient p=store.get(id);page.addView(Ui.text(this,"AGENDA",13,Ui.TEAL,true));page.addView(Ui.heading(this,"Citas"));page.addView(Ui.text(this,p==null?"Paciente":"Para "+p.getNombre()+" "+p.getApellidos(),16,Ui.MUTED,false));LinearLayout form=Ui.card(this);form.addView(Ui.text(this,"Programar una cita",19,Ui.INK,true));dateButton=Ui.button(this,"Elegir fecha",false);dateButton.setOnClickListener(v->pickDate());form.addView(dateButton);timeButton=Ui.button(this,"Elegir hora",false);timeButton.setOnClickListener(v->pickTime());form.addView(timeButton);reason=new EditText(this);reason.setSingleLine(true);reason.setTextSize(17);reason.setMinHeight(Ui.dp(this,54));reason.setHint("Motivo de la cita");reason.setContentDescription("Motivo de la cita, obligatorio");form.addView(reason);Button save=Ui.button(this,"Programar cita",true);save.setOnClickListener(v->save());form.addView(save);page.addView(form);page.addView(Ui.text(this,"PRÓXIMAS CITAS",13,Ui.MUTED,true));list=new LinearLayout(this);list.setOrientation(1);page.addView(list);Ui.showWithBack(this,page,"la ficha");initialDate=date;initialTime=time;updateButtons();render();}
 @Override protected void onResume(){super.onResume();if(store!=null)render();}
 @Override public void onBackPressed() {
     if (reason.length() > 0 || !initialDate.equals(date) || !initialTime.equals(time)) {
         Ui.confirmDiscard(this);
     } else {
         finish();
     }
 }
 private void pickDate(){Calendar c=Calendar.getInstance();new DatePickerDialog(this,(v,y,m,d)->{Calendar x=Calendar.getInstance();x.set(y,m,d);date=fmtDate(x);updateButtons();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void pickTime(){Calendar c=Calendar.getInstance();new TimePickerDialog(this,(v,h,m)->{time=String.format(Locale.getDefault(),"%02d:%02d",h,m);updateButtons();},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();}
 private void updateButtons(){dateButton.setText("Fecha: "+date);timeButton.setText("Hora: "+time);}
 private void save(){String why=reason.getText().toString().trim();if(why.isEmpty()){reason.setError("Indica el motivo");return;}Calendar chosen=Calendar.getInstance();try{String[] d=date.split("-");String[] t=time.split(":");chosen.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]),Integer.parseInt(t[0]),Integer.parseInt(t[1]),0);}catch(Exception e){return;}if(chosen.getTimeInMillis()<System.currentTimeMillis()-60000){Toast.makeText(this,"No se pueden programar citas en el pasado",Toast.LENGTH_SHORT).show();return;}if(store.slotTaken(id,date,time)){Toast.makeText(this,"Ya existe una cita para esa fecha y hora",Toast.LENGTH_SHORT).show();return;}store.addAppointment(id,date,time,why);initialDate=date;initialTime=time;reason.setText("");Toast.makeText(this,"Cita programada",Toast.LENGTH_SHORT).show();render();}
 private void render(){if(list==null)return;list.removeAllViews();for(String[] a:store.appointments(id)){LinearLayout row=Ui.card(this);row.setOrientation(0);TextView t=Ui.text(this,a[1]+" · "+a[2]+"\n"+a[3],16,Ui.INK,true);row.addView(t,new LinearLayout.LayoutParams(0,-2,1));Button cancel=Ui.button(this,"Cancelar",false);cancel.setContentDescription("Cancelar cita del "+a[1]+" a las "+a[2]);cancel.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("¿Cancelar esta cita?").setNegativeButton("Volver",null).setPositiveButton("Cancelar cita",(d,w)->{store.cancelAppointment(a[0]);render();}).show());row.addView(cancel);list.addView(row);}if(list.getChildCount()==0){LinearLayout c=Ui.card(this);c.addView(Ui.text(this,"Aún no hay citas programadas.",16,Ui.MUTED,false));list.addView(c);}}
 private String fmtDate(Calendar c){return new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(c.getTime());}
}
